//*****************************************************************************
// UPS / NUT dynamicky TCP dotaz
//
// Host / port / UPS name jsou z config.upsConfig.
// LINEA cte stav z NUT interne kazdych 5 s.
//
// Function pouziva Node.js modul "net", ktery musi byt v Setup:
//   net -> net
//
// Vystup 1:
//   kompletni NUT odpoved -> Parser UPS
//
// Vystup 2:
//   vysledek tlacitka Test NUT -> UPS CONFIG handler
//*****************************************************************************

const cfgAll = global.get("config") || {};
const saved = cfgAll.upsConfig || {};

const cfg = msg.upsConfigOverride
    ? { ...saved, ...msg.upsConfigOverride }
    : saved;

const host = String(cfg.host || "").trim();
const port = Number(cfg.port || 3493);
const upsName = String(cfg.upsName || "UPS").trim();
const timeoutMs = Math.max(500, Number(cfg.timeoutMs || 4000));

const isTest =
    msg.topic === "upsConfigTest" ||
    msg.forcePoll === true;

// LINEA -> NUT dotaz maximalne jednou za 5 s.
const POLL_MS = 5000;


//-----------------------------------------------------------------------------
// Pomocna zprava pro CONFIG UI
//-----------------------------------------------------------------------------

function testResult(ok, text) {
    return {
        topic: "upsTestResult",
        payload: text,
        ok: !!ok,
        host,
        port,
        upsName
    };
}


//-----------------------------------------------------------------------------
// Kontrola konfigurace
//-----------------------------------------------------------------------------

if (!host) {
    const text = "Chyba: chybi NUT host.";

    node.status({
        fill: "red",
        shape: "ring",
        text: "chybi NUT host"
    });

    if (isTest) {
        return [null, testResult(false, text)];
    }

    return null;
}


if (!Number.isFinite(port) || port < 1 || port > 65535) {
    const text = "Chyba: neplatny NUT port.";

    node.status({
        fill: "red",
        shape: "ring",
        text: "neplatny NUT port"
    });

    if (isTest) {
        return [null, testResult(false, text)];
    }

    return null;
}


if (!upsName) {
    const text = "Chyba: chybi UPS name.";

    node.status({
        fill: "red",
        shape: "ring",
        text: "chybi UPS name"
    });

    if (isTest) {
        return [null, testResult(false, text)];
    }

    return null;
}


//-----------------------------------------------------------------------------
// Polling 5 s
//-----------------------------------------------------------------------------

const now = Date.now();
const lastPoll = context.get("lastPoll") || 0;

if (!isTest && (now - lastPoll) < POLL_MS) {
    return null;
}

context.set("lastPoll", now);


//-----------------------------------------------------------------------------
// TCP komunikace
//-----------------------------------------------------------------------------

let finished = false;
let data = "";

const socket = net.createConnection({
    host: host,
    port: port
});

socket.setEncoding("utf8");
socket.setTimeout(timeoutMs);


//-----------------------------------------------------------------------------
// Stav komunikace
//-----------------------------------------------------------------------------

function markComm(ok, errorText = "") {

    const state = global.get("upsNutCommState") || {};

    state.ok = !!ok;
    state.lastAttempt = Date.now();

    if (ok) {
        state.lastOk = Date.now();
        state.lastError = "";
    } else {
        state.lastError = String(errorText || "NUT chyba");
    }

    state.host = host;
    state.port = port;
    state.upsName = upsName;

    global.set("upsNutCommState", state);
}


//-----------------------------------------------------------------------------
// Dokonceni dotazu
//-----------------------------------------------------------------------------

function finish(err = null) {

    if (finished) return;
    finished = true;


    //---------------------------------------------------------------------
    // TCP chyba
    //---------------------------------------------------------------------

    if (err) {

        markComm(false, err.message);

        const text =
            `NUT ${host}:${port} / ${upsName}: ${err.message}`;

        node.status({
            fill: "red",
            shape: "ring",
            text: text.slice(0, 45)
        });

        if (isTest) {
            node.send([
                null,
                testResult(false, text)
            ]);
        } else {
            node.error(text, msg);
        }

        return;
    }


    //---------------------------------------------------------------------
    // NUT ERR odpoved
    //---------------------------------------------------------------------

    const errMatch = data.match(/^ERR\s+(.+)$/m);

    if (errMatch) {

        const errLine = errMatch[1];

        markComm(false, `ERR ${errLine}`);

        const text =
            `NUT odpovedel ERR ${errLine}. ` +
            `Zkontroluj UPS name "${upsName}".`;

        node.status({
            fill: "red",
            shape: "ring",
            text: `ERR ${errLine}`
        });

        if (isTest) {
            node.send([
                null,
                testResult(false, text)
            ]);
        }

        return;
    }


    //---------------------------------------------------------------------
    // Kontrola, zda opravdu prisla UPS data
    //---------------------------------------------------------------------

    const hasBegin =
        data.includes(`BEGIN LIST VAR ${upsName}`);

    const hasVar =
        data.includes(`VAR ${upsName} `);

    if (!hasBegin && !hasVar) {

        markComm(false, "NUT bez UPS dat");

        const text =
            `TCP spojeni funguje, ale neprisla data pro UPS "${upsName}".`;

        node.status({
            fill: "yellow",
            shape: "ring",
            text: "NUT bez UPS dat"
        });

        if (isTest) {
            node.send([
                null,
                testResult(false, text)
            ]);
        }

        return;
    }


    //---------------------------------------------------------------------
    // Komunikace OK
    //---------------------------------------------------------------------

    const rxTs = Date.now();

    markComm(true);

    node.status({
        fill: "green",
        shape: "dot",
        text: `${host}:${port} · ${upsName}`
    });


    //---------------------------------------------------------------------
    // Zprava pro Parser UPS
    //---------------------------------------------------------------------

    const dataMsg = {
        ...msg,

        payload: data,

        _upsName: upsName,
        _nutHost: host,
        _nutPort: port,
        _nutRxTs: rxTs
    };

    delete dataMsg.upsConfigOverride;


    //---------------------------------------------------------------------
    // Vysledek TEST NUT
    //---------------------------------------------------------------------

    const result = isTest
        ? testResult(
            true,
            `OK: NUT ${host}:${port}, UPS "${upsName}" odpovida.`
        )
        : null;


    //---------------------------------------------------------------------
    // Odeslani
    //---------------------------------------------------------------------

    node.send([
        dataMsg,
        result
    ]);
}


//-----------------------------------------------------------------------------
// TCP udalosti
//-----------------------------------------------------------------------------

socket.on("connect", () => {

    node.status({
        fill: "blue",
        shape: "dot",
        text: `NUT ${host}:${port} ...`
    });

    socket.write(`LIST VAR ${upsName}\n`);
});


socket.on("data", chunk => {

    data += chunk;

    // Mame kompletni NUT odpoved.
    if (
        data.includes(`END LIST VAR ${upsName}`) ||
        /^ERR\s+/m.test(data)
    ) {

        // Nevolame destroy().
        // Po kompletni odpovedi korektne ukoncime zapisovou stranu socketu.
        socket.end();

        finish();
    }
});


socket.on("timeout", () => {

    // Timeout = komunikace selhala.
    // destroy() zde take nepotrebujeme.
    // Ukoncime spojeni a finish() oznaci komunikaci jako chybnou.

    try {
        socket.end();
    } catch (e) {
        // nic
    }

    finish(
        new Error(`timeout ${timeoutMs} ms`)
    );
});


socket.on("error", err => {

    finish(err);
});


socket.on("close", () => {

    // Nektere NUT implementace mohou spojeni ukoncit drive,
    // ale pritom uz mame platna data.
    if (!finished && data.length > 0) {
        finish();
    }
});


//-----------------------------------------------------------------------------
// Asynchronni Function - vysledek prijde pres node.send()
//-----------------------------------------------------------------------------

return null;

//*****************************************************************************
// Parser NUT odpovedi -> global.ups + change detection vypadku
// Autor: hacesoft 2026
//*****************************************************************************
const raw = (msg.payload || "").toString();
const out = {};

// Parsuj radky: VAR <upsName> <klic> "<hodnota>"
const expectedUpsName = String(msg._upsName || "").trim();
// NUT standardne posila radky jako CRLF (\\r\\n).
// Pri pouziti primeho Node.js TCP socketu tedy musime odstranit \\r,
// jinak regex nenajde zadny VAR radek a Dashboard nedostane nova data.
raw.split(/\r?\n/).forEach(line => {
    line = line.trimEnd();
    const m = line.match(/^VAR\s+(\S+)\s+(\S+)\s+"(.*)"$/);
    if (!m) return;
    if (expectedUpsName && m[1] !== expectedUpsName) return;
    out[m[2]] = m[3];
});

// Ochrana: prazdny/neuplny blok -> neprepisuj stary stav
if (!out["ups.status"] && out["battery.charge"] === undefined) {
    node.status({ fill: "yellow", shape: "ring", text: "prazdna odpoved" });
    return null;
}

const num = v => (v === undefined || v === "" ? null : parseFloat(v));

// --- Status a jeho rozklad ---
const statusRaw = out["ups.status"] || "?";
const flags = statusRaw.split(/\s+/);
const onBattery = flags.includes("OB");
const online = flags.includes("OL");
const lowBatt = flags.includes("LB");
const charging = flags.includes("CHRG");
const discharging = flags.includes("DISCHRG");
const overload = flags.includes("OVER");
const replaceBatt = flags.includes("RB");
const bypass = flags.includes("BYPASS");

let statusText, statusColor;
if (lowBatt) { statusText = "NIZKA BATERIE"; statusColor = "#f85149"; }
else if (onBattery) { statusText = "BEZI NA BATERII"; statusColor = "#ff9d2f"; }
else if (online) { statusText = "Sit OK"; statusColor = "#3fb950"; }
else { statusText = statusRaw; statusColor = "#888"; }

const extras = [];
if (charging) extras.push("nabiji");
if (discharging) extras.push("vybiji");
if (overload) extras.push("PRETIZENI");
if (replaceBatt) extras.push("VYMENIT BAT.");
if (bypass) extras.push("bypass");

const runtimeSec = num(out["battery.runtime"]);
const realpower = num(out["ups.realpower"]);
const loadPct = num(out["ups.load"]);
const powerNom = num(out["ups.realpower.nominal"]);

const ups = {
    mfr: out["device.mfr"] || out["ups.mfr"] || "",
    model: out["device.model"] || out["ups.model"] || "UPS",
    firmware: out["ups.firmware"] || "",
    serial: out["device.serial"] || out["ups.serial"] || "",
    statusRaw, statusText, statusColor,
    onBattery, online, lowBatt, charging, discharging, overload, replaceBatt, bypass,
    extras,
    charge: num(out["battery.charge"]),
    chargeLow: num(out["battery.charge.low"]),
    runtimeSec,
    runtimeMin: runtimeSec != null ? Math.floor(runtimeSec / 60) : null,
    runtimeTxt: runtimeSec != null
        ? `${Math.floor(runtimeSec / 60)}:${String(Math.round(runtimeSec % 60)).padStart(2, "0")}`
        : "-",
    battType: out["battery.type"] || "",
    battV: num(out["battery.voltage"]),
    load: loadPct,
    realpower,
    powerNom,
    powerVA: num(out["ups.power"]),
    powerNomVA: num(out["ups.power.nominal"]),
    headroomW: (powerNom != null && realpower != null) ? Math.max(powerNom - realpower, 0) : null,
    inputV: num(out["input.voltage"]),
    outputV: num(out["output.voltage"]),
    outputVnom: num(out["output.voltage.nominal"]),
    freq: num(out["output.frequency"]),
    freqNom: num(out["output.frequency.nominal"]),
    beeper: out["ups.beeper.status"] || "",
    ts: Date.now(),

    // LINEA -> NUT komunikace
    nutComm: {
        ok: true,
        lastOk: msg._nutRxTs || Date.now(),
        host: msg._nutHost || "",
        port: msg._nutPort || null,
        upsName: msg._upsName || ""
    }
};

global.set("ups", ups);

// =============================================================================
// LINEA API R2.2 - READ-ONLY UPS SNAPSHOT
// =============================================================================
// Verejne API obsahuje pouze provozni/monitorovaci udaje.
// Serial, interni sitove udaje a nepotrebna konfigurace se neexportuji.
// =============================================================================
global.set("lineaApiUpsState", {
    updatedAt: new Date().toISOString(),

    name: ups.model || "UPS",
    online: !!ups.online,
    onBattery: !!ups.onBattery,

    status: {
        raw: ups.statusRaw || null,
        lowBattery: !!ups.lowBatt,
        charging: !!ups.charging,
        discharging: !!ups.discharging,
        overload: !!ups.overload,
        replaceBattery: !!ups.replaceBatt,
        bypass: !!ups.bypass
    },

    battery: {
        chargePct: ups.charge ?? null,
        voltageV: ups.battV ?? null,
        runtimeSec: ups.runtimeSec ?? null
    },

    input: {
        voltageV: ups.inputV ?? null
    },

    output: {
        voltageV: ups.outputV ?? null,
        frequencyHz: ups.freq ?? null
    },

    load: {
        percent: ups.load ?? null,
        realPowerW: ups.realpower ?? null
    }
});


// --- Change detection prechodu stavu ---
const prev = flow.get("ups_prevStatus");
let event = null;
const cur = lowBatt ? "LB" : onBattery ? "OB" : online ? "OL" : "?";

if (prev && prev !== cur) {
    if (prev === "OL" && (cur === "OB" || cur === "LB")) event = "POWER_LOST";
    else if ((prev === "OB" || prev === "LB") && cur === "OL") event = "POWER_RESTORED";
    else if (cur === "LB") event = "BATTERY_LOW";
}
flow.set("ups_prevStatus", cur);

node.status({
    fill: online ? "green" : (lowBatt ? "red" : "yellow"),
    shape: "dot",
    text: `${statusText} | ${ups.charge ?? "-"}% | ${ups.runtimeTxt} | ${Object.keys(out).length} VAR`
});

const dataMsg = { payload: ups };
const eventMsg = event ? { topic: event, payload: ups } : null;
return [dataMsg, eventMsg];

//*****************************************************************************
// UPS udalost -> Dashboard toast + volitelne ntfy
//
// ntfy je POVINNE konfigurovano pres config.upsConfig.ntfyUrl.
// Pokud URL neni nastavena, dashboard zprava zustane funkcni,
// ale HTTP vystup se zablokuje pomoci msg._skipNtfy.
//*****************************************************************************
const u = msg.payload;
const cfg = (global.get("config") || {}).upsConfig || {};
const ntfyUrl = String(cfg.ntfyUrl || "").trim();

let text, color, title, priority, tags;
if (msg.topic === "POWER_LOST") {
    text = `Vypadek napajeni! UPS na baterii. Vydrz ~${u.runtimeMin} min.`;
    color = "#ff9d2f";
    title = "UPS: Vypadek napajeni";
    priority = "high";
    tags = "warning,electric_plug";
} else if (msg.topic === "POWER_RESTORED") {
    text = `Napajeni obnoveno. Baterie ${u.charge}%.`;
    color = "#3fb950";
    title = "UPS: Napajeni obnoveno";
    priority = "default";
    tags = "white_check_mark";
} else if (msg.topic === "BATTERY_LOW") {
    text = `NIZKA BATERIE! Hrozi vypnuti. Vydrz ~${u.runtimeMin} min.`;
    color = "#f85149";
    title = "UPS: NIZKA BATERIE";
    priority = "urgent";
    tags = "rotating_light";
} else {
    return null;
}

msg.color = color;
msg.payload = text;

if (!ntfyUrl) {
    msg._skipNtfy = true;
    return msg;
}

msg.url = ntfyUrl;
msg.method = "POST";
msg.headers = {
    "Title": title,
    "Priority": priority,
    "Tags": tags,
    "Content-Type": "text/plain; charset=utf-8"
};
msg._skipNtfy = false;

return msg;

// Buffer historie pro SVG graf - posila cele pole bodu.
const u = msg.payload;
if (!u || u.realpower == null) return null;

const MAX_POINTS = 720;
let hist = flow.get("ups_history") || [];

hist.push({
    t: u.ts || Date.now(),
    w: u.realpower,
    load: u.load,
    vin: u.inputV
});
if (hist.length > MAX_POINTS) hist = hist.slice(hist.length - MAX_POINTS);
flow.set("ups_history", hist);

msg.payload = hist;
return msg;

// UPS CONFIG handler
// 1 UI, 2 SAVE global config, 3 TEST NUT
const fSet=global.get("setConfigProperty");
const current=((global.get("config")||{}).upsConfig)||{};

function normalized(v) {
    v=v||{};
    return {
        host:String(v.host ?? current.host ?? "").trim(),
        port:Math.min(65535,Math.max(1,Number(v.port ?? current.port ?? 3493))),
        upsName:String(v.upsName ?? current.upsName ?? "UPS").trim() || "UPS",
        timeoutMs:Math.min(60000,Math.max(500,Number(v.timeoutMs ?? current.timeoutMs ?? 4000))),
        ntfyUrl:String(v.ntfyUrl ?? current.ntfyUrl ?? "").trim()
    };
}

if(msg.topic==="upsConfigGet"){
    return [{topic:"upsConfigData",payload:normalized(current)},null,null];
}

if(msg.topic==="upsConfigSave"){
    const cfg=normalized(msg.upsConfig);
    if(!cfg.host) return [{topic:"upsConfigStatus",payload:"Chyba: vypln NUT host.",ok:false},null,null];

    if(typeof fSet==="function"){
        for(const [k,v] of Object.entries(cfg)) fSet("upsConfig."+k,v);
    } else {
        const all=global.get("config")||{};
        all.upsConfig=cfg;
        global.set("config",all);
    }
    node.status({fill:"green",shape:"dot",text:`${cfg.host}:${cfg.port} · ${cfg.upsName}`});
    return [
        {topic:"upsConfigStatus",payload:"UPS konfigurace ulozena.",ok:true},
        {topic:"save",payload:"save"},
        null
    ];
}

if(msg.topic==="upsConfigTest"){
    const cfg=normalized(msg.upsConfig);
    if(!cfg.host) return [{topic:"upsConfigStatus",payload:"Chyba: vypln NUT host.",ok:false},null,null];
    return [
        {topic:"upsConfigStatus",payload:`Testuji ${cfg.host}:${cfg.port}, UPS "${cfg.upsName}"...`,testing:true},
        null,
        {forcePoll:true,topic:"upsConfigTest",upsConfigOverride:cfg}
    ];
}

if(msg.topic==="upsTestResult"){
    return [{
        topic:"upsConfigStatus",
        payload:String(msg.payload||""),
        ok:msg.ok===true,
        testing:false
    },null,null];
}
return null;

// NUT communication watchdog.
// Scheduler msg prichazi kazdou 1 s.
// OFFLINE = vice nez 15 s od posledni uspesne NUT odpovedi.
const state = global.get("upsNutCommState") || {};
const lastOk = Number(state.lastOk || 0);
const age = lastOk ? (Date.now() - lastOk) : Infinity;
const offline = age > 15000;

const prev = context.get("offline");
if (prev === offline) return null;
context.set("offline", offline);

msg.topic = "upsNutComm";
msg.payload = {
    ok: !offline,
    lastOk: lastOk || null,
    ageMs: Number.isFinite(age) ? age : null,
    error: state.lastError || "",
    host: state.host || "",
    port: state.port || null,
    upsName: state.upsName || ""
};

node.status({
    fill: offline ? "red" : "green",
    shape: offline ? "ring" : "dot",
    text: offline ? "NUT OFFLINE" : "NUT OK"
});

return msg;
